SELECT sm.sm_type, sm.sm_carrier, SUM(cs.cs_ext_sales_price) AS total_catalog_sales, COUNT(ws.ws_order_number) AS web_order_count FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk JOIN web_sales ws ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk WHERE cs.cs_sold_date_sk = CAST(2450844 AS integer) AND ws.ws_sold_date_sk = CAST(2451898 AS integer) GROUP BY sm.sm_type, sm.sm_carrier
